hooks.command:
bash -c 'echo "$CLAUDE_TOOL_INPUT" | python3 -c "
import sys, json, re
try:
    inp = json.load(sys.stdin)
    path = inp.get(\"file_path\", \"\")
    content = inp.get(\"new_string\", \"\") or inp.get(\"content\", \"\")
except Exception:
    sys.exit(0)
keeplist = [\"Store\", \"WebView\", \"VCLibs\", \"UI.Xaml\", \"Defender\", \"DesktopAppInstaller\"]
if \"debloat_list.txt\" in path:
    for kw in keeplist:
        # Only flag unconditional removal (lines not inside a comment)
        for line in content.splitlines():
            stripped = line.strip()
            if stripped.startswith(\"#\"):
                continue
            if kw.lower() in stripped.lower():
                print(f\"[BLOCKED] debloat_list.txt: pattern matches protected AppX keep-list entry: {kw}\", flush=True)
                sys.exit(2)
"'
